import React from 'react';
import {AbsoluteFill,interpolateColors} from 'remotion';
import {useS,T,en,DUR,Easing,interpolate,clamp,FONT,Destello,golpe} from './kit';
// FE 2026-11-28 06:00 oracion "¿Otra vez las tres de la mañana, Señor?" Estilo 2.5D (Vol, capas, giro, sombras en el suelo).
// Madrugada en azul cobalto, luz cian del celular, farola naranja y al final el primer dorado del amanecer. Sin texto dibujado ni rostro de Dios.
export const SUBS={arriba:130,size:78,acento:'#FFD27A'};
const P=(x:number)=>x-0.2; // la imagen entra 6 cuadros antes de su palabra
const SH=[0,P(en('tres')),P(en('Señor')),P(en('mente')),P(en('duermes')),P(en('conmigo')),P(en('cama')),P(en('techo')),P(en('respiración')),T(42),P(en('silencio')),T(49)-.1,P(en('entra')),P(en('entra',2)),P(en('conversación')),P(en('miedo')),T(73)-.2,P(en('nada')),P(en('completa')),P(en('pongo')),P(en('Toma')),P(en('reloj')),P(en('almohada')),P(en('entender')),P(en('descansar')),P(en('despierto')),P(en('tres',2)),P(en('contigo')),P(en('Amén'))];
const q=(s:number,a:number,b:number)=>interpolate(s,[a,Math.max(a+.01,b)],[0,1],{...clamp,easing:Easing.inOut(Easing.cubic)});
const lin=(s:number,a:number,b:number)=>interpolate(s,[a,Math.max(a+.01,b)],[0,1],clamp);
const mix=(a:number,b:number,k:number)=>a+(b-a)*k;
const col=(k:number,a:string,b:string)=>interpolateColors(Math.max(0,Math.min(1,k)),[0,1],[a,b]);
const R=(n:number)=>{const v=Math.sin(n*127.1+31.7)*43758.5453;return v-Math.floor(v);};
const ell=(cx:number,cy:number,rx:number,ry:number)=>`M${cx-rx} ${cy}a${rx} ${ry} 0 1 0 ${2*rx} 0a${rx} ${ry} 0 1 0 ${-2*rx} 0Z`;
const caps=(x1:number,y1:number,x2:number,y2:number,w:number)=>{const a=Math.atan2(y2-y1,x2-x1),r=w/2,nx=-Math.sin(a)*r,ny=Math.cos(a)*r;
 return `M${x1+nx} ${y1+ny}L${x2+nx} ${y2+ny}A${r} ${r} 0 0 0 ${x2-nx} ${y2-ny}L${x1-nx} ${y1-ny}A${r} ${r} 0 0 0 ${x1+nx} ${y1+ny}Z`;};
type C3=[string,string,string];
const SKIN:C3=['#f6d0aa','#d99a66','#8a4c28'],SKING:C3=['#ffe6d2','#f2b48e','#a85e40'],HAIR:C3=['#5a4638','#241610','#080402'];
const WOOD:C3=['#e0a46c','#8f5632','#3a1a0a'],WOOD2:C3=['#c98a56','#7a4624','#2c1306'],GOLD:C3=['#fff2b0','#ffc93a','#9a6100'],LUZ:C3=['#ffffff','#ffe9a0','#e0a020'];
const CREAM:C3=['#ffffff','#d2e0ff','#6f84c8'],BLUE:C3=['#a8dcff','#2f78ff','#0a2a9a'],GRAY:C3=['#f0f3f8','#a9b3c8','#4d5870'];
// Volumen: color medio, sombra suave abajo-derecha, luz suave arriba-izquierda y borde fino.
const Vol:React.FC<{id:string;d:string;c:C3;sw?:number;o?:number;borde?:string}>=({id,d,c,sw=70,o=24,borde})=><g>
 <defs><clipPath id={id}><path d={d}/></clipPath></defs>
 <path d={d} fill={c[1]}/>
 <g clipPath={`url(#${id})`}>
  <path d={d} fill='none' stroke={c[2]} strokeWidth={sw} filter='url(#b18)' transform={`translate(${-o} ${-o})`}/>
  <path d={d} fill='none' stroke={c[0]} strokeWidth={sw*.75} filter='url(#b18)' transform={`translate(${o} ${o})`}/>
 </g>
 <path d={d} fill='none' stroke={borde||c[2]} strokeWidth={3} opacity={.55}/>
</g>;
const Brillo2:React.FC<{x:number;y:number;rx:number;ry:number;r?:number;o?:number}>=({x,y,rx,ry,r=-30,o=.75})=><ellipse cx={x} cy={y} rx={rx} ry={ry} transform={`rotate(${r} ${x} ${y})`} fill='#fff' opacity={o} filter='url(#b6)'/>;
const Defs:React.FC=()=><defs>
 <filter id='b6' x='-50%' y='-50%' width='200%' height='200%'><feGaussianBlur stdDeviation='6'/></filter>
 <filter id='b18' x='-50%' y='-50%' width='200%' height='200%'><feGaussianBlur stdDeviation='18'/></filter>
 <filter id='b40' x='-50%' y='-50%' width='200%' height='200%'><feGaussianBlur stdDeviation='40'/></filter>
 <radialGradient id='oroG'><stop stopColor='#fff6c8' stopOpacity='.95'/><stop offset='1' stopColor='#ffc93a' stopOpacity='0'/></radialGradient>
 <radialGradient id='farG'><stop stopColor='#ffd070' stopOpacity='.95'/><stop offset='.4' stopColor='#ff8a1e' stopOpacity='.55'/><stop offset='1' stopColor='#ff6a00' stopOpacity='0'/></radialGradient>
 <radialGradient id='azulG'><stop stopColor='#9fe0ff' stopOpacity='.9'/><stop offset='1' stopColor='#2f8fff' stopOpacity='0'/></radialGradient>
 <linearGradient id='rayo' x1='0' y1='0' x2='0' y2='1'><stop stopColor='#fffbe6' stopOpacity='.9'/><stop offset='1' stopColor='#ffe9a8' stopOpacity='.3'/></linearGradient>
 <linearGradient id='cianF' x1='0' y1='0' x2='0' y2='1'><stop stopColor='#4ff3ff' stopOpacity='0'/><stop offset='.45' stopColor='#4ff3ff' stopOpacity='.05'/><stop offset='1' stopColor='#4ff3ff' stopOpacity='.5'/></linearGradient><linearGradient id='cian' x1='0' y1='0' x2='0' y2='1'><stop stopColor='#dcffff'/><stop offset='1' stopColor='#12b8ff'/></linearGradient>
 <radialGradient id='caraR' cx='.4' cy='.35'><stop stopColor='#ffffff'/><stop offset='.7' stopColor='#e8f0ff'/><stop offset='1' stopColor='#aebfe8'/></radialGradient>
 <linearGradient id='piel' x1='0' y1='0' x2='1' y2='1'><stop stopColor={SKIN[0]}/><stop offset='.55' stopColor={SKIN[1]}/><stop offset='1' stopColor={SKIN[2]}/></linearGradient>
</defs>;
const Bokeh:React.FC<{s:number;i:number;cerca?:boolean;c:string}>=({s,i,cerca=false,c})=><g>{Array.from({length:cerca?6:14}).map((_,j)=>{const r=cerca?60+((j*37+i*11)%70):18+((j*29+i*7)%40);const x=((j*263+i*97)%1300)-110,y=((j*389+i*151)%2100)-90;return <circle key={j} cx={x+Math.sin(s*.6+j)*30} cy={y+Math.cos(s*.5+j)*30} r={r} fill={cerca?'#fff':c} opacity={cerca?.09:.35} filter={cerca?'url(#b18)':'url(#b6)'}/>;})}</g>;
// ---------- Mano con volumen: palma, nudillos, dedos de dos falanges (caps) y uñas ----------
const dedo=(bx:number,by:number,a:number,L:number,w:number,curl:number)=>{const ar=a*Math.PI/180,mx=bx+Math.sin(ar)*L*.55,my=by-Math.cos(ar)*L*.55,a2=ar+curl*1.3,tx=mx+Math.sin(a2)*L*.45,ty=my-Math.cos(a2)*L*.45;
 return {d:caps(bx,by,mx,my,w)+caps(mx,my,tx,ty,w*.9),tx,ty,deg:a2*180/Math.PI};};
const Mano:React.FC<{id:string;x:number;y:number;r?:number;k?:number;curl?:number;c?:C3;nail?:string;mx?:number;rel?:boolean}>=({id,x,y,r=0,k=1,curl=0,c=SKIN,nail='#ffd8d0',mx=1,rel=false})=>{
 const F:[number,number,number,number][]=rel?[[-36,-22,-4,76],[-12,-34,-1,92],[12,-34,1,88],[36,-24,4,68]]:[[-46,-22,-9,82],[-15,-36,-2,98],[18,-36,3,96],[48,-24,10,78]];
 const th=rel?dedo(-44,70,-28,82,36,-curl*.3):dedo(-52,62,-62,86,38,-curl*.6),fw=rel?30:32;
 return <g transform={`translate(${x} ${y}) rotate(${r}) scale(${k*mx} ${k})`}>
  {F.map(([bx,by,a,L],j)=>{const f=dedo(bx,by,a,L,fw,curl);return <g key={j}><Vol id={id+'f'+j} d={f.d} c={c} sw={22} o={6}/><ellipse cx={f.tx} cy={f.ty} rx={10} ry={12} transform={`rotate(${f.deg} ${f.tx} ${f.ty})`} fill={nail} stroke={c[2]} strokeWidth={2}/></g>;})}
  <Vol id={id+'t'} d={th.d} c={c} sw={24} o={7}/><ellipse cx={th.tx} cy={th.ty} rx={11} ry={13} transform={`rotate(${th.deg} ${th.tx} ${th.ty})`} fill={nail} stroke={c[2]} strokeWidth={2}/>
  <Vol id={id+'p'} d='M-62 -26Q-70 60 -42 118Q0 142 42 118Q74 60 62 -26Q0 -48 -62 -26Z' c={c} sw={60} o={16}/>
  {[-46,-15,18,48].map((nx,j)=><path key={j} d={`M${nx-12} -22Q${nx} -34 ${nx+12} -22`} stroke={c[2]} strokeWidth={4} fill='none' opacity={.55}/>)}
  <path d='M-20 60Q0 85 24 62' stroke={c[2]} strokeWidth={4} fill='none' opacity={.4}/>
 </g>;};
const Cel:React.FC<{id:string;x:number;y:number;r?:number;k?:number;on?:number;flip?:number;sy?:number}>=({id,x,y,r=0,k=1,on=1,flip=1,sy=1})=><g transform={`translate(${x} ${y}) rotate(${r}) scale(${k*Math.abs(flip)} ${k*sy})`}>
 <ellipse cx={14} cy={20} rx={95} ry={175} fill='#000' opacity={.28} filter='url(#b18)'/>
 <Vol id={id} d='M-75 -120A30 30 0 0 1 -45 -150H45A30 30 0 0 1 75 -120V120A30 30 0 0 1 45 150H-45A30 30 0 0 1 -75 120Z' c={flip>0?['#5a6a90','#1c2440','#05070f']:['#6a7a9c','#2a3454','#080c18']} sw={40} o={10}/>
 {flip>0?<><path d='M-65 -115A22 22 0 0 1 -43 -138H43A22 22 0 0 1 65 -115V115A22 22 0 0 1 43 138H-43A22 22 0 0 1 -65 115Z' fill='url(#cian)' opacity={on}/><Brillo2 x={-30} y={-90} rx={18} ry={60} r={20} o={.5*on}/></>
 :<><circle cx={-35} cy={-105} r={22} fill='#0a0f20' stroke='#7a8ab0' strokeWidth={4}/><circle cx={-40} cy={-110} r={6} fill='#fff' opacity={.7}/></>}
</g>;
// ---------- Reloj de mesa redondo SIN números: campanas, patas, aro, dos agujas doradas ----------
const Reloj:React.FC<{id:string;x:number;y:number;k?:number;h:number;m:number;gold?:number;sh?:number}>=({id,x,y,k=1,h,m,gold=0,sh=0})=><g transform={`translate(${x} ${y}) scale(${k})`}>
 <ellipse cy={250} rx={240} ry={36} fill='#000' opacity='.38' filter='url(#b18)'/>
 {gold>0&&<circle r={440} fill='url(#oroG)' opacity={gold*.9}/>}
 <Vol id={id+'l1'} d={caps(-130,170,-180,245,36)} c={['#7a8ad0','#2a3a8a','#0a1040']} sw={20} o={5}/><Vol id={id+'l2'} d={caps(130,170,180,245,36)} c={['#7a8ad0','#2a3a8a','#0a1040']} sw={20} o={5}/>
 <g transform={`rotate(${sh} 0 -210)`}><Vol id={id+'bl'} d='M-215 -165C-215 -255 -85 -270 -70 -185Z' c={GOLD} sw={30} o={8}/><Vol id={id+'br'} d='M215 -165C215 -255 85 -270 70 -185Z' c={GOLD} sw={30} o={8}/><path d={caps(0,-215,0,-262,12)} fill='#9a6100'/><circle cy={-266} r={14} fill='#ffc93a'/></g>
 <Vol id={id+'b'} d={ell(0,0,205,205)} c={['#f1f6ff','#7d95d6','#1b2c78']} sw={90} o={28}/>
 <circle r={168} fill='url(#caraR)'/><circle r={168} fill='none' stroke='#8aa0e0' strokeWidth={5}/>
 {Array.from({length:12}).map((_,j)=><circle key={j} cx={Math.sin(j*Math.PI/6)*138} cy={-Math.cos(j*Math.PI/6)*138} r={j%3===0?11:6} fill='#26358a'/>)}
 <g transform={`rotate(${h})`}><Vol id={id+'h'} d={caps(0,8,0,-98,28)} c={GOLD} sw={14} o={4}/></g>
 <g transform={`rotate(${m})`}><Vol id={id+'m'} d={caps(0,12,0,-140,20)} c={GOLD} sw={12} o={4}/></g>
 <circle r={19} fill='#ffc93a' stroke='#9a6100' strokeWidth={3}/><Brillo2 x={-6} y={-8} rx={7} ry={5} o={.9}/>
 <Brillo2 x={-70} y={-85} rx={62} ry={22} r={-38} o={.55}/>
</g>;
// ---------- Rostro del hombre de 40: piel trigueña, barba de dos días, ojos con iris, párpado y parpadeo ----------
const FACE='M0 -250C120 -250 185 -150 182 -20C180 110 110 215 0 232C-110 215 -180 110 -182 -20C-185 -150 -120 -250 0 -250Z';
const Rostro:React.FC<{id:string;s:number;eyes?:number;brow?:number;smile?:number;luz?:number;warm?:number;look?:number}>=({id,s,eyes=1,brow=0,smile=0,luz=0,warm=0,look=1})=>{
 const kk=s%3.3,bl=kk<.16?Math.abs(kk-.08)/.08*.9+.1:1,o=eyes*bl,sm=smile;
 return <g>
 {[-1,1].map(k=><Vol key={k} id={id+'e'+k} d={ell(k*182,12,32,54)} c={SKIN} sw={26} o={8}/>)}
 <Vol id={id+'h'} d={FACE} c={SKIN} sw={130} o={36}/>
 <path d='M-176 30C-150 150 -80 218 0 232C80 218 150 150 176 30C140 84 90 104 0 108C-90 104 -140 84 -176 30Z' fill={HAIR[1]} opacity={.42} filter='url(#b6)'/>
 <Vol id={id+'r'} d='M-190 -30C-215 -190 -110 -285 8 -283C140 -283 220 -185 192 -30C172 -100 150 -150 100 -172C40 -140 -50 -150 -105 -178C-150 -150 -172 -95 -190 -30Z' c={HAIR} sw={60} o={16}/>
 {[-1,1].map(k=><g key={k} transform={`translate(${k*72} -22)`}>
  <defs><clipPath id={id+'c'+k}><path d={`M-38 2Q0 ${-32*o} 38 2Q0 ${26*o} -38 2Z`}/></clipPath></defs>
  <path d={`M-38 2Q0 ${-32*o} 38 2Q0 ${26*o} -38 2Z`} fill='#fff'/>
  <g clipPath={`url(#${id}c${k})`}><circle cy={look*6} r={19} fill='#6a4220'/><circle cy={look*6} r={19} fill='none' stroke='#2a1608' strokeWidth={3}/><circle cy={look*6} r={9} fill='#050505'/><circle cx={6} cy={look*6-7} r={5.5} fill='#fff'/></g>
  <path d={`M-38 2Q0 ${-32*o-(1-o)*-6} 38 2`} stroke='#2a160c' strokeWidth={6+ (1-o)*3} fill='none' strokeLinecap='round'/>
  <path d={`M${-k*38} ${-50-(1-brow)*18}Q0 ${-68-(1-brow)*8} ${k*42} ${-46+(1-brow)*6}`} stroke={HAIR[1]} strokeWidth={13} fill='none' strokeLinecap='round'/></g>)}
 <path d='M-14 -20C-20 25 -48 55 -42 78C-30 98 -12 92 0 98C12 92 30 98 42 78C48 55 20 25 14 -20' fill={SKIN[1]} stroke={SKIN[2]} strokeWidth={3}/><path d='M6 -10C10 30 26 55 30 72' stroke={SKIN[0]} strokeWidth={6} fill='none' opacity='.8' strokeLinecap='round'/>
 {[-1,1].map(k=><ellipse key={k} cx={k*17} cy={86} rx={9} ry={5} fill='#4a2210'/>)}
 <path d={`M-58 ${143-sm*16}C-30 128 -10 135 0 132C10 135 30 128 58 ${143-sm*16}C30 ${150-sm*4} -30 ${150-sm*4} -58 ${143-sm*16}Z`} fill='#b04a56'/>
 <path d={`M-55 ${145-sm*16}C-30 170 30 170 55 ${145-sm*16}C30 ${155-sm*4} -30 ${155-sm*4} -55 ${145-sm*16}Z`} fill='#d9707a'/><path d='M-20 160Q0 166 20 160' stroke='#fff' strokeWidth={4} opacity='.5' fill='none'/>
 {luz>0&&<path d={FACE} fill='#7ff4ff' opacity={luz*.15}/>}
 {warm>0&&<path d={FACE} fill='#ffd070' opacity={warm*.3}/>}
 </g>;};
// ---------- Cuadro 1: ojo en primerísimo plano, iluminado de cian por la pantalla ----------
const OjoGrande:React.FC<{s:number}>=({s})=>{
 const o=1-.95*Math.max(0,Math.sin(Math.PI*lin(s,.12,.62))),yc=30-500*o,yb=30+300*o;
 const eye=`M-340 30Q0 ${yc} 340 30Q0 ${yb} -340 30Z`,dx=Math.sin(s*2)*8,dy=30+Math.cos(s*1.7)*6;
 return <g transform='translate(540 980)'>
  <rect x={-900} y={-1100} width={1800} height={2200} fill='url(#piel)'/>
  <ellipse cy={-300} rx={560} ry={170} fill={SKIN[2]} opacity={.5} filter='url(#b40)'/><ellipse cy={250} rx={400} ry={80} fill={SKIN[2]} opacity={.32} filter='url(#b40)'/>
  <ellipse cx={-120} cy={-130} rx={380} ry={60} fill='#fff' opacity={.18} filter='url(#b40)'/>
  <path d='M-430 -330Q-100 -440 430 -340Q300 -280 -100 -300Q-330 -290 -430 -330Z' fill={HAIR[1]} opacity={.5} filter='url(#b6)'/>
  {Array.from({length:70}).map((_,j)=>{const x=-440+j*12.6+R(j)*6,y=-340+Math.pow(x/440,2)*60-Math.sin((x+440)/880*Math.PI)*60+R(j+3)*14,sl=(x<0?14:26)+R(j+7)*14,L=44+R(j+5)*26;return <path key={j} d={`M${x} ${y+24}Q${x+sl*.4} ${y} ${x+sl} ${y-L}`} stroke={j%4?HAIR[1]:HAIR[0]} strokeWidth={5+R(j+1)*5} fill='none' strokeLinecap='round'/>;})}
  <path d={`M-300 -20Q0 ${-20-(500*o+170)/2} 300 -20`} stroke={SKIN[2]} strokeWidth={14} fill='none' opacity={.55} filter='url(#b6)'/>
  <defs><clipPath id='ojoc'><path d={eye}/></clipPath>
   <radialGradient id='irisG'><stop stopColor='#ffd890'/><stop offset='.45' stopColor='#b8761e'/><stop offset='1' stopColor='#2e1606'/></radialGradient>
   <radialGradient id='escG' cx='.5' cy='.45'><stop stopColor='#ffffff'/><stop offset='.75' stopColor='#eef4ff'/><stop offset='1' stopColor='#b8cdee'/></radialGradient>
   <linearGradient id='sombraG' x1='0' y1='0' x2='0' y2='1'><stop stopColor='#000' stopOpacity='.55'/><stop offset='.5' stopColor='#000' stopOpacity='0'/></linearGradient></defs>
  <path d={eye} fill='url(#escG)'/>
  <g clipPath='url(#ojoc)'>
   <path d='M-330 40Q-250 70 -180 20M330 40Q260 80 190 30' stroke='#e07070' strokeWidth={4} fill='none' opacity={.4}/>
   <g transform={`translate(${dx} ${dy})`}>
    <circle r={152} fill='url(#irisG)'/>
    {Array.from({length:40}).map((_,j)=>{const a=j*9*Math.PI/180;return <path key={j} d={`M${Math.cos(a)*66} ${Math.sin(a)*66}L${Math.cos(a)*148} ${Math.sin(a)*148}`} stroke={j%2?'#5a2a08':'#ffd38a'} strokeWidth={3} opacity={.45}/>;})}
    <circle r={152} fill='none' stroke='#1a0c04' strokeWidth={10}/>
    <circle r={58+Math.sin(s*3)*3} fill='#030303'/>
    <rect x={-84} y={-92} width={74} height={104} rx={12} fill='#e8ffff' opacity={.88} transform='rotate(-8)'/><rect x={-72} y={-80} width={50} height={80} rx={8} fill='#7ae8ff' opacity={.6} transform='rotate(-8)'/>
    <circle cx={64} cy={-58} r={15} fill='#fff' opacity={.9}/>
   </g>
   <rect x={-360} y={-300} width={720} height={420} fill='url(#sombraG)'/>
  </g>
  <path d={`M-340 30Q0 ${yc} 340 30`} stroke='#150a05' strokeWidth={24} fill='none' strokeLinecap='round'/>
  {Array.from({length:30}).map((_,j)=>{const t=j/29,x=-330+660*t,y=(1-t)*(1-t)*30+2*(1-t)*t*yc+t*t*30,v=(t-.5);return <path key={j} d={`M${x} ${y}Q${x+v*30} ${y-24} ${x+v*70} ${y-48}`} stroke='#150a05' strokeWidth={6} fill='none' strokeLinecap='round'/>;})}
  <path d={`M-340 30Q0 ${yb} 340 30`} stroke={SKIN[2]} strokeWidth={8} fill='none' opacity={.7}/>
  <ellipse cx={-322} cy={40} rx={26} ry={20} fill='#e87a80' opacity={.8}/>
  <rect x={-900} y={-500} width={1800} height={1600} fill='url(#cianF)'/>
 </g>;};
// ---------- Cielo de noche (afuera): estrellas que titilan, rayo de luz blanca cálida bajando hacia la casa ----------
const Cielo:React.FC<{s:number;p:number;id:string;rot?:number;fugaz?:number}>=({s,p,id,rot=0,fugaz=-9})=>{
 const yb=mix(-100,1480,p),fu=lin(s,fugaz,fugaz+.8);
 return <g>
  <defs><linearGradient id={id+'g'} x1='0' y1='0' x2='0' y2='1'><stop stopColor='#0a1fa8'/><stop offset='.6' stopColor='#1f64ff'/><stop offset='1' stopColor='#6ec0ff'/></linearGradient></defs>
  <rect x={-400} y={-700} width={1900} height={2800} fill={`url(#${id}g)`}/>
  <g transform={`rotate(${rot+s*1.1} 540 700)`}>{Array.from({length:110}).map((_,j)=>{const x=R(j)*1900-400,y=R(j+99)*1500-500,r=1.6+R(j+7)*3.2;return <g key={j} opacity={.3+.7*Math.abs(Math.sin(s*(1+R(j+3)*2)+j))}><circle cx={x} cy={y} r={r} fill='#fff'/>{j%6===0&&<path d={`M${x-r*4} ${y}H${x+r*4}M${x} ${y-r*4}V${y+r*4}`} stroke='#fff' strokeWidth={1.5}/>}</g>;})}</g>
